const { owner_id = '', item_name = '' } = query;
const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

try {
  const result = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/rest/v1/stock_movements',
    headers: {
      apikey: serviceKey,
      Authorization: 'Bearer ' + serviceKey
    },
    qs: {
      owner_id: 'eq.' + owner_id,
      item_name: 'ilike.*' + item_name + '*',
      type: 'eq.entrada',
      select: 'item_name,unit_cost,quantity,created_at,supplier',
      order: 'created_at.desc',
      limit: '5'
    }
  });
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'buscar_preco_historico' });
}

const {
  owner_id = '',
  name = '',
  category = 'outros',
  unit = 'kg',
  cost_price = 0,
  supplier = '',
  current_stock = 0,
  min_stock = 0,
  setor = '',
  metadata_setor = '{}'
} = query;

const supabaseUrl = ($env && $env.SUPABASE_URL) ? $env.SUPABASE_URL : 'https://SEU_PROJETO.supabase.co';
const serviceKey  = ($env && $env.SUPABASE_SERVICE_KEY) ? $env.SUPABASE_SERVICE_KEY : 'SUA_SERVICE_KEY';

let meta = {};
try { meta = typeof metadata_setor === 'string' ? JSON.parse(metadata_setor) : metadata_setor; } catch (_) {}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: supabaseUrl + '/rest/v1/stock_items',
    headers: {
      apikey: serviceKey,
      Authorization: 'Bearer ' + serviceKey,
      'Content-Type': 'application/json',
      Prefer: 'resolution=merge-duplicates,return=minimal'
    },
    body: JSON.stringify({ owner_id, name, category, unit, cost_price: Number(cost_price), supplier, current_stock: Number(current_stock), min_stock: Number(min_stock), sector: setor, sector_metadata: meta })
  });
  return JSON.stringify({ success: true, saved: name });
} catch (e) {
  return JSON.stringify({ error: e.message, tool: 'salvar_insumo' });
}

const item = items[0];
const raw = item.json.output || item.json.text || item.json;
let data;
try {
  const clean = (typeof raw === 'string') ? raw.replace(/```json\n?/gi, '').replace(/```/g, '').trim() : JSON.stringify(raw);
  data = JSON.parse(clean);
} catch (e) {
  data = { raw_output: raw };
}
return [{ json: { success: true, agente: 'INGESTAO', setor: item.json.setor, owner_id: item.json.owner_id, timestamp: new Date().toISOString(), data } }];
